hold_ticks := 0
if ((#Study_Presence).presenceSensor_presence == false) {
hold_ticks = hold_ticks + 1
    if (hold_ticks >= 9001) {
(#Study_Light).light_moveToBrightness(20.0, 0.0)
        delay(10 MIN)
(#Study_Light).switch_off()
        break
}
}
else {
hold_ticks = 0
}

